## 8. Express server (`server.js`)

```js
// server.js
require('dotenv').config();
const express = require('express');
const session = require('express-session');
const cors = require('cors');
const mongoose = require('mongoose');
const path = require('path');

const { getRequestToken, handleCallback } = require('./auth');
const User = require('./models/User');
const { findMatches } = require('./utils/matcher');

const app = express();

// ---------- Middleware ----------
app.use(cors({ origin: true, credentials: true }));
app.use(express.json());
app.use(
  session({
    secret: process.env.SESSION_SECRET,
    resave: false,
    saveUninitialized: false,
    cookie: { maxAge: 24 * 60 * 60 * 1000 }, // 1 day
  })
);

// ---------- DB ----------
mongoose
  .connect(process.env.MONGODB_URI)
  .then(() => console.log('MongoDB connected'))
  .catch(err => console.error('Mongo error', err));

// ---------- Static front‑end ----------
app.use(express.static(path.join(__dirname, 'public')));

// ---------- Auth routes ----------
app.get('/auth/twitter', getRequestToken);
app.get('/auth/twitter/callback', handleCallback);

// ---------- API: current user profile ----------
app.get('/api/me', async (req, res) => {
  if (!req.session.userId) return res.json(null);
  const user = await User.findById(req.session.userId).lean();
  res.json(user);
});

// ---------- API: find matches ----------
app.get('/api/matches', async (req, res) => {
  if (!req.session.userId) return res.status(401).send('Not logged in');

  const current = await User.findById(req.session.userId).lean();
  const all = await User.find().lean();

  const matches = await findMatches(current, all);
  res.json(matches);
});

// ---------- Logout ----------
app.post('/api/logout', (req, res) => {
  req.session.destroy(() => res.sendStatus(200));
});

// ---------- Fallback for SPA ----------
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

// ---------- Start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`🚀 Server listening on ${PORT}`));
```

**What this file does**

| Section | Purpose |
|--------|---------|
| `express-session` | Keeps the logged‑in user’s Mongo `_id` in a cookie‑based session. |
| `/auth/twitter` | Starts the OAuth flow (`getRequestToken`). |
| `/auth/twitter/callback` | Handles the redirect from Twitter (`handleCallback`). |
| `/api/me` | Returns the logged‑in user’s profile (including interests). |
| `/api/matches` | Runs the matcher against **all** stored users and returns those with ≥ 30 % overlap. |
| `public/index.html` | Serves a tiny UI (see next step). |

