## 9. Tiny front‑end (`public/index.html`)

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Twitter‑Match Dating</title>
  <style>
    body { font-family: Arial, sans-serif; max-width: 600px; margin: 2rem auto; }
    .profile, .match { border: 1px solid #ddd; padding: 1rem; margin: 1rem 0; border-radius: 8px; }
    img { border-radius: 50%; }
    button { padding: .5rem 1rem; }
  </style>
</head>
<body>
  <h1>❤️ Twitter‑Match Dating</h1>

  <div id="app"></div>

  <script>
    async function loadMe() {
      const res = await fetch('/api/me', { credentials: 'include' });
      return res.ok ? await res.json() : null;
    }

    async function loadMatches() {
      const res = await fetch('/api/matches', { credentials: 'include' });
      return res.ok ? await res.json() : [];
    }

    async function render() {
      const user = await loadMe();
      const app = document.getElementById('app');

      if (!user) {
        app.innerHTML = `<a href="/auth/twitter"><button>Log in with Twitter</button></a>`;
        return;
      }

      // show own profile
      app.innerHTML = `
        <div class="profile">
          <img src="${user.avatarUrl}" alt="avatar"><br>
          <strong>${user.name}</strong> (@${user.username})<br>
          Interests: ${user.interests.join(', ')}
          <br><button id="logout">Log out</button>
        </div>
        <h2>Potential Matches</h2>
        <div id="matches"></div>
      `;

      document.getElementById('logout').onclick = async () => {
        await fetch('/api/logout', { method: 'POST', credentials: 'include' });
        location.reload();
      };

      const matches = await loadMatches();
      const matchesDiv = document.getElementById('matches');

      if (matches.length === 0) {
        matchesDiv.textContent = 'No matches yet – tweet about more things!';
        return;
      }

      matchesDiv.innerHTML = matches.map(m => `
        <div class="match">
          <img src="${m.avatarUrl}" alt="avatar" width="48"><br>
          <strong>${m.name}</strong> (@${m.username})<br>
          Similarity: ${m.similarity}
        </div>
      `).join('');
    }

    render();
  </script>
</body>
</html>
```

*The UI does three things:*  

* Shows a **Login with Twitter** button when not authenticated.  
* After login, displays the user’s **avatar, name, and extracted interests**.  
* Calls `/api/matches` and lists any other users that share enough interests.

